   const response = await fetch(apiUrl(path), {
     method: "POST",
     headers: { "Content-Type": "application/json", Accept: "application/json" },
     body: body === undefined ? undefined : JSON.stringify(body),
   });
   if (!response.ok) {
     throw new Error(await errorDetail(response));
