+import { useCallback, useEffect, useRef, useState } from "react";
+
+import { transcribeAudio } from "../../api/studioApi";
+import { AudioRecorder, RecorderError, describeRecorderFailure } from "../../lib/recorder";
+import {
+  SpeechError,
+  browserSpeechSupported,
+  choosePath,
+  describeSpeechFailure,
+  transcribeWithBrowserSpeech,
+} from "../../lib/speech";
+import type { TranscriptionMode } from "../../types";
+
+type MicState = "idle" | "recording" | "transcribing" | "unsupported";
+
+export interface MicButtonProps {
+  /** The transcribed text, ready to be reviewed in the composer. */
+  onTranscript: (text: string) => void;
+  /** Raised when a recording or transcription fails. */
+  onError: (message: string) => void;
+  /** True while the copilot is replying; the mic waits its turn. */
+  disabled?: boolean;
+  /** Which transcription path to try first. */
+  mode: TranscriptionMode;
+  /** The model name sent to the backend's transcription endpoint. */
+  model: string;
+}
+
+const STATE_LABELS: Record<MicState, string> = {
+  idle: "Record",
+  recording: "Stop",
+  transcribing: "Transcribing…",
+  unsupported: "Record",
+};
+
+const STATE_ALT_LABELS: Record<MicState, string> = {
+  idle: "Record voice message",
+  recording: "Stop recording",
+  transcribing: "Transcribing voice message",
+  unsupported: "Voice input is unavailable",
+};
+
+function formatElapsed(ms: number): string {
+  const totalSeconds = Math.floor(ms / 1000);
+  const minutes = Math.floor(totalSeconds / 60);
+  const seconds = totalSeconds % 60;
+  return `${minutes}:${String(seconds).padStart(2, "0")}`;
+}
+
+/**
+ * The microphone beside the composer.
+ *
+ * Recording never sends anything. It produces a transcript, which the owner
+ * places in the composer for review — the human keeps the last word, exactly
+ * as they do with the inline cards.
+ */
+export function MicButton({
+  onTranscript,
+  onError,
+  disabled = false,
+  mode,
+  model,
+}: MicButtonProps) {
+  const [state, setState] = useState<MicState>("idle");
+  const [elapsed, setElapsed] = useState(0);
+  const recorderRef = useRef<AudioRecorder | null>(null);
+  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
+
+  const path = choosePath(mode);
+  const serverReady = Boolean(model);
+  const browserReady = path === "browser" && browserSpeechSupported();
+  const supported = path === "browser" ? browserReady : serverReady;
+
+  const clearTimer = useCallback(() => {
+    if (timerRef.current !== null) {
+      clearInterval(timerRef.current);
+      timerRef.current = null;
+    }
+  }, []);
+
+  const stopTimer = useCallback(() => {
+    clearTimer();
+    setElapsed(0);
+  }, [clearTimer]);
+
+  // A recording that outlives the component would leave the browser's
+  // recording indicator on. Cancel it on unmount.
+  useEffect(() => {
+    return () => {
+      clearTimer();
+      recorderRef.current?.cancel();
+      recorderRef.current = null;
+    };
+  }, [clearTimer]);
+
+  const beginServerRecording = useCallback(async () => {
+    const recorder = new AudioRecorder();
+    recorderRef.current = recorder;
+    try {
+      await recorder.start();
+    } catch (error) {
+      recorderRef.current = null;
+      const reason = error instanceof RecorderError ? error.reason : "unsupported";
+      onError(describeRecorderFailure(reason));
+      setState("idle");
+      return;
+    }
+
+    setState("recording");
+    setElapsed(0);
+    timerRef.current = setInterval(() => {
+      setElapsed(recorder.elapsedMs);
+    }, 250);
+  }, [onError]);
+
+  const beginBrowserSpeech = useCallback(async () => {
+    setState("transcribing");
+    try {
+      const text = await transcribeWithBrowserSpeech();
+      if (text) {
+        onTranscript(text);
+      } else {
+        onError(describeSpeechFailure("no-speech"));
+      }
+    } catch (error) {
+      const reason = error instanceof SpeechError ? error.reason : "error";
+      onError(describeSpeechFailure(reason));
+    } finally {
+      setState("idle");
+    }
+  }, [onError, onTranscript]);
+
+  const stopRecording = useCallback(async () => {
+    const recorder = recorderRef.current;
+    recorderRef.current = null;
+    stopTimer();
+    if (!recorder) {
+      setState("idle");
+      return;
+    }
+
+    setState("transcribing");
+    try {
+      const blob = await recorder.stop();
+      if (blob.size === 0) {
+        onError(describeRecorderFailure("no-device"));
+        setState("idle");
+        return;
+      }
+      const result = await transcribeAudio(blob, model);
+      if (result.text) {
+        onTranscript(result.text);
+      } else {
+        onError(describeSpeechFailure("no-speech"));
+      }
+    } catch (error) {
+      onError(
+        error instanceof Error
+          ? error.message
+          : describeRecorderFailure("unsupported"),
+      );
+    } finally {
+      setState("idle");
+    }
+  }, [model, onError, onTranscript, stopTimer]);
+
+  const cancelRecording = useCallback(() => {
+    recorderRef.current?.cancel();
+    recorderRef.current = null;
+    stopTimer();
+    setState("idle");
+  }, [stopTimer]);
+
+  useEffect(() => {
+    function onKeyDown(event: KeyboardEvent) {
+      if (event.key === "Escape" && state === "recording") {
+        event.preventDefault();
+        cancelRecording();
+      }
+    }
+    window.addEventListener("keydown", onKeyDown);
+    return () => window.removeEventListener("keydown", onKeyDown);
+  }, [cancelRecording, state]);
+
+  const effectiveState: MicState = supported ? state : "unsupported";
+
+  async function handleClick() {
+    if (!supported || disabled) {
+      return;
+    }
+    if (state === "recording") {
+      await stopRecording();
+      return;
+    }
+    if (path === "browser") {
+      await beginBrowserSpeech();
+      return;
+    }
+    await beginServerRecording();
+  }
+
+  const reason = !supported
+    ? path === "browser"
+      ? "This browser has no speech recognition. The studio will transcribe a recording instead."
+      : "Set a transcription model in Settings to record voice messages."
+    : "";
+
+  return (
+    <span className="chat-mic">
+      <button
+        type="button"
+        className={`studio-button chat-mic__button chat-mic__button--${effectiveState}`}
+        onClick={() => void handleClick()}
+        disabled={disabled || !supported}
+        aria-label={STATE_ALT_LABELS[effectiveState]}
+        title={reason || STATE_LABELS[effectiveState]}
+      >
+        <span aria-hidden="true" className="chat-mic__glyph">
+          {effectiveState === "recording" ? "■" : "🎤"}
+        </span>
+        <span className="chat-mic__label">{STATE_LABELS[effectiveState]}</span>
+      </button>
+      {effectiveState === "recording" ? (
+        <span className="chat-mic__elapsed" aria-live="polite">
+          {formatElapsed(elapsed)}
+        </span>
+      ) : null}
+    </span>
+  );
+}

