+/**
+ * Microphone capture for the copilot's voice input.
+ *
+ * The browser gives us two ways to hear the user, and they fail in different
+ * places. `getUserMedia` + `MediaRecorder` needs a secure context and a
+ * granted microphone permission; the browser's own `SpeechRecognition` needs
+ * a vendor implementation. This module owns the first path and the failure
+ * vocabulary both paths share.
+ */
+
+/** Why a recording could not be made. */
+export type RecorderFailureReason =
+  | "unsupported"
+  | "insecure"
+  | "denied"
+  | "no-device"
+  | "no-recorder";
+
+/** The user-facing message for each failure. Specific beats vague. */
+const FAILURE_MESSAGES: Record<RecorderFailureReason, string> = {
+  unsupported: "This browser cannot record audio. Use the desktop app or a Chromium browser.",
+  insecure: "Recording needs a secure connection. Open the studio over https or on localhost.",
+  denied: "Microphone access was denied. Allow it in your browser's site settings.",
+  "no-device": "No microphone was found.",
+  "no-recorder": "This browser cannot record audio.",
+};
+
+/** The MIME types we can record, best first. */
+const PREFERRED_MIME_TYPES = [
+  "audio/webm;codecs=opus",
+  "audio/webm",
+  "audio/mp4",
+];
+
+/** Thrown when a recording cannot be started or completed. */
+export class RecorderError extends Error {
+  readonly reason: RecorderFailureReason;
+
+  constructor(reason: RecorderFailureReason) {
+    super(FAILURE_MESSAGES[reason]);
+    this.name = "RecorderError";
+    this.reason = reason;
+  }
+}
+
+/** The user-facing message for a failure reason. */
+export function describeRecorderFailure(reason: RecorderFailureReason): string {
+  return FAILURE_MESSAGES[reason];
+}
+
+/** True when this browser exposes the APIs needed to record audio. */
+export function recorderSupported(): boolean {
+  return (
+    typeof navigator !== "undefined" &&
+    typeof navigator.mediaDevices?.getUserMedia === "function" &&
+    typeof window !== "undefined" &&
+    typeof window.MediaRecorder === "function"
+  );
+}
+
+/**
+ * True when the page may capture the microphone.
+ *
+ * `isSecureContext` is the modern check, but some webviews do not implement
+ * it. A `localhost` origin is trustworthy by specification, so it is accepted
+ * as a fallback.
+ */
+export function isSecureContextOk(): boolean {
+  if (typeof window === "undefined") {
+    return false;
+  }
+  if (typeof window.isSecureContext === "boolean") {
+    return window.isSecureContext;
+  }
+  const host = window.location?.hostname ?? "";
+  return host === "localhost" || host === "127.0.0.1" || host === "[::1]";
+}
+
+/**
+ * The best audio MIME type this browser can record.
+ *
+ * Safari only offers `audio/mp4`; Chromium offers `audio/webm`. An empty
+ * string means "let the browser choose", which is the last resort.
+ */
+export function pickAudioMimeType(): string {
+  if (typeof window === "undefined" || typeof window.MediaRecorder !== "function") {
+    return "";
+  }
+  for (const candidate of PREFERRED_MIME_TYPES) {
+    try {
+      if (window.MediaRecorder.isTypeSupported(candidate)) {
+        return candidate;
+      }
+    } catch {
+      // Some browsers throw rather than return false. Keep probing.
+    }
+  }
+  return "";
+}
+
+/** Map a `getUserMedia` rejection onto a reason the user can act on. */
+export function reasonFromMediaError(error: unknown): RecorderFailureReason {
+  const name = (error as { name?: string } | null)?.name ?? "";
+  switch (name) {
+    case "NotAllowedError":
+    case "PermissionDeniedError":
+    case "SecurityError":
+    case "NotReadableError":
+    case "TrackStartError":
+      return "denied";
+    case "NotFoundError":
+    case "DevicesNotFoundError":
+    case "OverconstrainedError":
+      return "no-device";
+    default:
+      return "denied";
+  }
+}
+
+interface RecorderInternals {
+  stream: MediaStream;
+  recorder: MediaRecorder;
+  chunks: Blob[];
+  startedAt: number;
+}
+
+/**
+ * A single microphone recording.
+ *
+ * The caller drives it: `start()`, then `stop()` for the audio or `cancel()`
+ * to throw it away. Both stop every track, so the browser's recording
+ * indicator never outlives the button.
+ */
+export class AudioRecorder {
+  private internals: RecorderInternals | null = null;
+
+  /** Milliseconds since the recording started. */
+  get elapsedMs(): number {
+    if (!this.internals) {
+      return 0;
+    }
+    return Date.now() - this.internals.startedAt;
+  }
+
+  /** True while audio is being captured. */
+  get active(): boolean {
+    return this.internals !== null;
+  }
+
+  /**
+   * Begin capturing.
+   *
+   * @throws RecorderError when the browser cannot record, the page is not
+   * secure, the user denied the microphone, or no microphone exists.
+   */
+  async start(): Promise<void> {
+    if (this.internals) {
+      return;
+    }
+    if (!recorderSupported()) {
+      throw new RecorderError("unsupported");
+    }
+    if (!isSecureContextOk()) {
+      throw new RecorderError("insecure");
+    }
+
+    let stream: MediaStream;
+    try {
+      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
+    } catch (error) {
+      throw new RecorderError(reasonFromMediaError(error));
+    }
+
+    const mimeType = pickAudioMimeType();
+    let recorder: MediaRecorder;
+    try {
+      recorder = mimeType
+        ? new window.MediaRecorder(stream, { mimeType })
+        : new window.MediaRecorder(stream);
+    } catch {
+      stream.getTracks().forEach((track) => track.stop());
+      throw new RecorderError("no-recorder");
+    }
+
+    const chunks: Blob[] = [];
+    recorder.ondataavailable = (event: BlobEvent) => {
+      if (event.data && event.data.size > 0) {
+        chunks.push(event.data);
+      }
+    };
+
+    this.internals = { stream, recorder, chunks, startedAt: Date.now() };
+    recorder.start();
+  }
+
+  /**
+   * Stop capturing and return the recorded audio.
+   *
+   * @throws RecorderError when no recording is in progress.
+   */
+  async stop(): Promise<Blob> {
+    const internals = this.internals;
+    if (!internals) {
+      throw new RecorderError("unsupported");
+    }
+    this.internals = null;
+
+    const blob = await new Promise<Blob>((resolve) => {
+      internals.recorder.onstop = () => {
+        resolve(new Blob(internals.chunks, { type: internals.recorder.mimeType }));
+      };
+      try {
+        internals.recorder.stop();
+      } catch {
+        // A recorder that never started cannot fire onstop.
+        resolve(new Blob(internals.chunks, { type: internals.recorder.mimeType }));
+      }
+    });
+
+    internals.stream.getTracks().forEach((track) => track.stop());
+    return blob;
+  }
+
+  /** Stop capturing and throw the audio away. */
+  cancel(): void {
+    const internals = this.internals;
+    if (!internals) {
+      return;
+    }
+    this.internals = null;
+    try {
+      internals.recorder.onstop = null;
+      internals.recorder.stop();
+    } catch {
+      // Already stopped; nothing to do.
+    }
+    internals.stream.getTracks().forEach((track) => track.stop());
+  }
+}

