+/**
+ * Ambient declarations for the Web Speech API.
+ *
+ * TypeScript's `lib.dom.d.ts` ships `SpeechRecognitionAlternative`,
+ * `SpeechRecognitionResult`, and `SpeechRecognitionResultList`, but not the
+ * `SpeechRecognition` interface itself or the `webkitSpeechRecognition`
+ * global. Safari and Chrome only expose the prefixed constructor, so both
+ * spellings are declared here.
+ */
+
+interface SpeechRecognitionEvent extends Event {
+  readonly results: SpeechRecognitionResultList;
+  readonly resultIndex: number;
+}
+
+interface SpeechRecognitionErrorEvent extends Event {
+  readonly error: string;
+  readonly message: string;
+}
+
+interface SpeechRecognition extends EventTarget {
+  continuous: boolean;
+  interimResults: boolean;
+  lang: string;
+  maxAlternatives: number;
+  onresult: ((event: SpeechRecognitionEvent) => void) | null;
+  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null;
+  onend: ((event: Event) => void) | null;
+  onstart: ((event: Event) => void) | null;
+  start(): void;
+  stop(): void;
+  abort(): void;
+}
+
+interface SpeechRecognitionConstructor {
+  prototype: SpeechRecognition;
+  new (): SpeechRecognition;
+}
+
+declare const SpeechRecognition: SpeechRecognitionConstructor;
+declare const webkitSpeechRecognition: SpeechRecognitionConstructor;
+
+interface Window {
+  SpeechRecognition?: SpeechRecognitionConstructor;
+  webkitSpeechRecognition?: SpeechRecognitionConstructor;
+}
